with RecentTransactions as (select * from transactions where txn_time >= '2024-11-05' and (txn_type = 'DEBIT' or txn_type in ('FEE', 'CREDIT', 'REFUND'))), transactions_stats as (select txn_type, merchant, round((100 * sum(case when txn_type = 'REFUND' then 1 else 0 end)) / count(*), 1) pct_refund, round(avg(amount), 2) avg_amount from RecentTransactions group by txn_type, merchant) select * from transactions_stats where pct_refund >= 43 order by txn_type desc;
